#!/usr/bin/env node
// Native placement, editing, topology and production geometry for independent machinery.
const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto'),assert=require('node:assert/strict'),{chromium}=require('playwright');
const root=path.resolve(__dirname,'..'),url=process.argv[2]||'http://127.0.0.1:8876',output=path.resolve(process.argv[3]||path.join(root,'docs/benchmarks/engine-core-browser.json')),imageRoot=path.resolve(process.env.ENGINE_CORE_IMAGES||path.join(root,'docs/images')),diagnostic=process.env.ENGINE_CORE_DIAGNOSTIC==='1';
if(diagnostic&&!process.argv[3])throw Error('A diagnostic run requires an explicit temporary output');
if(process.env.ENGINE_CORE_ONLY&&!diagnostic)throw Error('An isolated scenario is diagnostic-only');
const manifest=JSON.parse(fs.readFileSync(path.join(root,'index.html'),'utf8').match(/window\.KS_FILES=(\{[^\n]+\});/)[1]),files=[...new Set(['index.html',...manifest.data,...['core','gfx','app','engine','worker'].map(k=>manifest[k]),'js/lang-en.js','js/i18n.js','scripts/browser-engine-core.cjs'])],sources=()=>Object.fromEntries(files.map(f=>[f,crypto.createHash('sha256').update(fs.readFileSync(path.join(root,f))).digest('hex')])),name='Independent engine core browser',near=(a,b,label)=>assert.ok(Number.isFinite(a)&&Math.abs(a-b)<=Math.max(1,Math.abs(b))*1e-8,`${label||'value'}: ${a} != ${b}`);
const note=label=>process.stderr.write(label+'\n');
async function ready(page){await page.waitForFunction(name=>{const Y=window.__yard;return Y.ship?.name===name&&Y.stats&&Y.eng.adoptedGen>=Y.eng.gen&&Y.eng.geoGen>=Y.eng.gen&&Y.eng.statsGen>=Y.eng.gen;},name,{timeout:180000});}
async function reveal(locator){for(let attempt=0;attempt<4;attempt++){await locator.waitFor({state:'attached'});await locator.evaluate(el=>{const ancestors=[];for(let p=el;p;p=p.parentElement)if(p.tagName==='DETAILS')ancestors.unshift(p);for(const p of ancestors)p.open=true;});await locator.page().evaluate(()=>new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r))));try{await locator.waitFor({state:'visible',timeout:2000});await locator.scrollIntoViewIfNeeded({timeout:5000});return;}catch(error){if(attempt===3)throw error;}}}
async function click(page,selector){const locator=page.locator(selector).first();await reveal(locator);await locator.click();}
async function number(page,selector,value){const locator=page.locator(selector).first();await reveal(locator);await locator.fill(String(value));await locator.dispatchEvent('change');}
async function select(page,selector,value){const locator=page.locator(selector).first();await reveal(locator);await locator.selectOption(String(value));}
async function tab(page,key){if(await page.evaluate(key=>window.__yard.st.tab!==key||window.__yard.st.dockCollapsed,key))await click(page,`#tabs [data-tab="${key}"]`);}
async function engineNumber(page,field,value,fresh=false){await number(page,`[data-engine-field="${field}"][data-engine-new="${fresh?'1':'0'}"]`,value);if(!fresh){await ready(page);await draw(page);}}
async function coordinates(page,p){for(let i=0;i<3;i++)await number(page,'#newP'+['X','Y','Z'][i],p[i]);await click(page,'#btnAtCoordinates');await ready(page);}
async function editPart(page,id){await tab(page,'edit');await click(page,`#panel [data-edpick="parts:${id}"]`);await page.waitForFunction(id=>window.__yard.st.sel?.id===id,id);}
async function move(page,id,delta){await editPart(page,id);for(let i=0;i<3;i++)await number(page,`[data-xfd="${i}"]`,delta[i]);await click(page,'[data-xfgo="move"]');await ready(page);}
async function draw(page){await page.evaluate(async()=>{const Y=window.__yard;Y.draw();Y.kickLoop();await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));});}
async function nativeInspection(page,coreId){
 note('Native canvas selection and read-only feed/shaft inspection');await tab(page,'systems');const checked=[];
 for(const kind of ['core','feed','shaft']){
  const point=await page.evaluate(({kind,coreId})=>{const Y=window.__yard,C=Y.C,v=Y.view(),p=kind==='core'?Y.ship.parts.find(p=>p.id===coreId):(kind==='feed'?C.engineTransmission(Y.ship):C.engineDriveRoutes(Y.ship)).parts[0],points=p.segments?.flatMap(s=>[.2,.4,.6,.8].map(t=>C.add(s.a,C.mul(s.u,s.l*t))))||[p.c];
   for(const th of [-.8,.8,1.7,-1.7,2.7])for(const ph of [.55,1.1,1.8]){Object.assign(v.cam,{ortho:true,target:C.add(p.c,v.off),r:120,th,ph});for(const position of points){const q=v.project(position),hit=Y.pick(q[0],q[1],{parts:true,fits:false}),el=document.elementFromPoint(q[0],q[1]);if(hit?.part?.id===p.id&&el?.closest('#viewport')&&!el.closest('button,#dock,#toolRail,.hudbar'))return {x:q[0],y:q[1],id:p.id,routeId:p.routeId,kind};}}
   return null;
  },{kind,coreId});assert.ok(point,'a visible point on the actual '+kind+' geometry can be picked');await draw(page);await page.mouse.click(point.x,point.y);await page.waitForFunction(({id,kind})=>{const q=window.__yard.st.inspect;return kind==='core'?q?.list==='parts'&&q.id===id:q?.part?.id===id;},point);if(!(await page.evaluate(()=>window.__yard.st.selInfo)))await click(page,'#panel [data-selinfo]');const title=await page.locator('#panel .sel-strip .ss-t b').innerText(),text=await page.locator('#panel .sel-info').innerText();assert.doesNotMatch(text,/NaN|undefined|Infinity/);if(kind==='feed'){assert.match(title,/推進配電路/);assert.match(text,/電送効率/);}if(kind==='shaft'){assert.match(title,/機関動力伝達路/);assert.doesNotMatch(text,/電送効率/);}checked.push({...point,title,text});
 }
 return checked;
}
async function systemsInspection(page){
 const text={};for(const id of ['engine-transmission-editor','engine-drive-editor','propulsion-preview']){const panel=page.locator('#'+id);await reveal(panel);text[id]=await panel.innerText();assert.doesNotMatch(text[id],/NaN|undefined|Infinity/);}
 assert.match(text['engine-transmission-editor'],/推進配電路[\s\S]*総経路長/);assert.match(text['engine-drive-editor'],/機関からノズルへの動力伝達路[\s\S]*動力伝達路の質量/);assert.match(text['propulsion-preview'],/配電路の損失熱\s+(?!0(?:\.0)?\s*W)[\d.]+×10/);await reveal(page.locator('#engine-transmission-editor'));return text;
}
