 assert.ok(proof.cores.length>=2);assert.equal(proof.nozzles.length,7);assert.ok(proof.nozzles.every(p=>p.sourceFaces>0&&p.sourceFaces===p.renderedFaces&&p.sourceVertices===p.renderedVertices),'complete native bell roots survive independent engine ownership');assert.equal(proof.shafts.length,7);assert.ok(proof.feed.length>0);assert.ok(proof.cores.every(c=>c.id>0&&c.volume>0));assert.ok(proof.nozzles.every(p=>p.vented&&proof.cores.some(c=>c.id===p.machineryId)));
 const primary=proof.nozzles.filter(p=>[20,21,22].includes(p.id)),secondary=proof.nozzles.filter(p=>[23,24,25,26].includes(p.id)),primaryOwnerIds=[...new Set(primary.map(p=>p.machineryId))],secondaryOwnerIds=[...new Set(secondary.map(p=>p.machineryId))];assert.equal(primary.length,3);assert.equal(secondary.length,4);assert.ok(primaryOwnerIds.every(id=>!secondaryOwnerIds.includes(id)),'primary and secondary engine bodies remain separate');for(const id of primaryOwnerIds){const core=proof.cores.find(c=>c.id===id),reactor=proof.reactors.find(r=>r.id===core.reactorId);assert.ok(reactor&&reactor.c[0]>core.c[0],'primary machinery is aft of its reactor');}
