async function parts(page){return page.evaluate(()=>{const Y=window.__yard;return JSON.parse(Y.C.publicJSON(Y.ship.parts));});}
async function runtime(page){return page.evaluate(()=>{const Y=window.__yard,C=Y.C,profile=C.fleetProfile(Y.stats,Y.ship.name,Y.ship),u=C.fleetUnit('engine-core-browser','engine-core-browser',profile,0);C.heatInit(u);C.allocateShipPower(u,C.fleetSystems(u),{throttle:1,shields:0,weapons:0},1,'balanced');const p=u.propulsion,H=C.heatStatus(u);return{ratedInputW:p.ratedInputW,actualInputW:p.actualInputW,actualThrustN:p.actualThrustN,wasteHeatW:p.wasteHeatW,cores:p.cores,engines:p.engines,power:{draw:p.power.draw,delivered:p.power.delivered,feedLossW:p.power.feedLossW,edgeLosses:p.power.edgeLosses,consumers:p.power.consumers,sources:p.power.sources},heat:{mode:profile.heat.mode,engineNodes:profile.heat.src.filter(s=>s.k==='engine').map(s=>({id:s.id,modules:s.m})),feedNodes:profile.heat.src.filter(s=>s.k==='feed').map(s=>({id:s.id,routeId:s.routeId,modules:s.m})),feedLossW:H?.feedLossW,feedLossJ:H?.feedLossJ,pendingFeedJ:u.ht.feedE?.reduce((n,v)=>n+v,0)||0},electricalRuns:C.engineTransmission(Y.ship).routes.map(r=>({id:r.id,ok:r.ok,length:r.length,efficiency:r.efficiency,capacityW:r.capacityW})),lossPerM:C.ENGINE_FEED_LOSS_PER_M,profileOwners:profile.propulsion.cores?.map(c=>({id:c.id,moduleIndex:c.moduleIndex})),generation:{design:Y.eng.gen,geometry:Y.eng.geoGen,statistics:Y.eng.statsGen}};});}
function assertFlow(flow,label){assert.equal(flow.cores.length,1,label+' one real machine consumes power once');near(flow.ratedInputW,1e21,label+' rated input');assert.ok(flow.actualInputW>0&&flow.actualInputW<=8e20*(1+1e-9),label+' actual input respects the finite source trunk');near(flow.cores[0].actualInputW,flow.actualInputW,label+' one owner input');near(flow.engines.reduce((n,e)=>n+e.actualInputW,0),flow.actualInputW,label+' outlet allocation does not duplicate machine input');near(flow.engines.reduce((n,e)=>n+e.shaftReceivedW,0),flow.cores[0].shaftOutputW,label+' real shaft output reaches the outlets');near(flow.cores[0].shaftOutputW,.95*flow.actualInputW,label+' useful machine output');near(flow.wasteHeatW,.05*flow.actualInputW,label+' actual machine waste');near(flow.power.draw,flow.power.delivered+flow.power.feedLossW,label+' electrical energy conservation');assert.ok(flow.power.feedLossW>0,label+' length loss makes real heat');near(flow.power.feedLossW,flow.power.edgeLosses.reduce((n,e)=>n+e.heatW,0),label+' routed loss ledger');near(flow.heat.feedLossJ,flow.power.feedLossW,label+' one second of physical wire heat');near(flow.heat.pendingFeedJ,flow.heat.feedLossJ,label+' losses enter the feed heat nodes');assert.equal(flow.heat.engineNodes.length,1,label+' one machine heat node');assert.ok(flow.heat.feedNodes.length>=2,label+' individual feed runs own real heat nodes');assert.equal(flow.heat.mode,'strict');for(const r of flow.electricalRuns){assert.ok(r.ok);near(r.efficiency,Math.exp(-flow.lossPerM*r.length),label+' physical length loss '+r.id);}}

